WITH roster AS ( SELECT DISTINCT a.expert_id AS agent_id FROM hive.care.expert_performance_metrics a WHERE CAST(a."date" AS DATE) BETWEEN DATE '2026-07-18' AND DATE '2026-08-28' AND LOWER(a.icp_client) IN ( 'mob-at&t','mob-verizon','pss-at&t','pss-at&t nac','pss-verizon','xbox','mcafee' ) ), present_call AS ( SELECT b.partner_agent_id AS agent_id, CAST(date_add('day', 4, date_trunc('week', CAST(b."created_at" AS DATE))) AS DATE) AS week_ending, b.template_questions_phrase AS behavior_raw, MAX(CASE WHEN LOWER(TRIM(b.response_recommendation_advancedevidences_operator)) = 'is_present' THEN 1 ELSE 0 END) AS is_present FROM hive.care.l3_asurion_observe_autoqa_evaluations b JOIN roster r ON r.agent_id = b.partner_agent_id WHERE CAST(b."created_at" AS DATE) BETWEEN DATE '2026-07-18' AND DATE '2026-08-28' AND b.template_questions_name = 'Advanced Discovery Call Flow V1' GROUP BY 1, 2, 3, b.meeting_id ), behavior_week AS ( SELECT agent_id, week_ending, CASE TRIM(regexp_replace(behavior_raw, '\s*:\s*$', '')) WHEN 'Confirm Resolution' THEN 'Confirm Resolution (Advanced Discovery)' WHEN 'Transition Statement' THEN 'Transition Statement (Advanced Discovery)' ELSE TRIM(regexp_replace(behavior_raw, '\s*:\s*$', '')) END AS behavior, SUM(is_present) AS numerator FROM present_call GROUP BY 1, 2, 3 ), calls_taken AS ( SELECT b.partner_agent_id AS agent_id, CAST(date_add('day', 4, date_trunc('week', CAST(b."created_at" AS DATE))) AS DATE) AS week_ending, COUNT(DISTINCT b.meeting_id) AS denominator FROM hive.care.l3_asurion_observe_autoqa_evaluations b JOIN roster r ON r.agent_id = b.partner_agent_id WHERE CAST(b."created_at" AS DATE) BETWEEN DATE '2026-07-18' AND DATE '2026-08-28' AND b.template_questions_name = 'Advanced Discovery Call Flow V1' GROUP BY 1, 2 ) SELECT bw.agent_id AS agent_id, bw.week_ending AS week_ending, 'all' AS call_type, 'Advanced Discovery Call Flow V1' AS scorecard_name, bw.behavior AS behavior, CAST(bw.numerator AS DOUBLE) AS numerator, CAST(ct.denominator AS DOUBLE) AS denominator, CASE WHEN ct.denominator IS NULL OR ct.denominator = 0 THEN NULL ELSE CAST(bw.numerator AS DOUBLE) / ct.denominator END AS calc FROM behavior_week bw JOIN calls_taken ct ON ct.agent_id = bw.agent_id AND ct.week_ending = bw.week_ending
